CREATE TABLE evlet_api_keys (id INTEGER PRIMARY KEY AUTOINCREMENT, "user_id" INTEGER NOT NULL REFERENCES "evlet_users"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "prefix" TEXT NOT NULL, "hash" TEXT NOT NULL, "scope" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "last_used" INTEGER, "revoked_at" INTEGER, UNIQUE ("prefix"));
