CREATE TABLE evlet_mail_links ("model" TEXT NOT NULL, "record_id" INTEGER NOT NULL, "message_key" TEXT NOT NULL, "entry_id" INTEGER NOT NULL, PRIMARY KEY ("model", "record_id", "message_key", "entry_id"));
CREATE TABLE evlet_mail_states ("hash" TEXT PRIMARY KEY, "user_id" INTEGER NOT NULL REFERENCES "evlet_users"("id") ON DELETE CASCADE, "provider" TEXT NOT NULL, "secrets" BLOB NOT NULL, "expires" INTEGER NOT NULL);
CREATE TABLE evlet_mailboxes (id INTEGER PRIMARY KEY AUTOINCREMENT, "user_id" INTEGER NOT NULL REFERENCES "evlet_users"("id") ON DELETE CASCADE, "provider" TEXT NOT NULL, "address" TEXT NOT NULL, "settings" TEXT NOT NULL, "secrets" BLOB, "status" TEXT NOT NULL, "error" TEXT, "cursor" TEXT, "linking" INTEGER NOT NULL DEFAULT 1, "created_at" INTEGER NOT NULL, "attempted_at" INTEGER, "synced_at" INTEGER, UNIQUE ("user_id"));
CREATE TABLE evlet_mcp_clients (id INTEGER PRIMARY KEY AUTOINCREMENT, "user_id" INTEGER NOT NULL REFERENCES "evlet_users"("id") ON DELETE CASCADE, "oauth_client" TEXT NOT NULL REFERENCES "evlet_oauth_clients"("id") ON DELETE CASCADE, "client_name" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "last_used" INTEGER, "calls" INTEGER NOT NULL DEFAULT 0, "allow_changes" INTEGER NOT NULL DEFAULT 0, "apps" TEXT, "revoked_at" INTEGER);
CREATE TABLE evlet_mcp_tokens ("hash" TEXT PRIMARY KEY, "client_id" INTEGER NOT NULL REFERENCES "evlet_mcp_clients"("id") ON DELETE CASCADE, "kind" TEXT NOT NULL, "expires" INTEGER NOT NULL, "used" INTEGER NOT NULL DEFAULT 0, CHECK ("kind" IN ('access', 'refresh')));
CREATE TABLE evlet_migrations ("position" INTEGER PRIMARY KEY, "name" TEXT NOT NULL, "checksum" TEXT NOT NULL, UNIQUE ("name"));
CREATE TABLE evlet_money ("id" INTEGER PRIMARY KEY, "scale" INTEGER NOT NULL, CHECK ("id" = 1));
INSERT INTO "evlet_money" VALUES(1,6);
CREATE TABLE evlet_oauth_clients ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "redirect_uris" TEXT NOT NULL, "secret" TEXT, "auth_method" TEXT NOT NULL DEFAULT 'none', "created_at" INTEGER NOT NULL, CHECK ("auth_method" IN ('none', 'client_secret_post', 'client_secret_basic')));
CREATE TABLE evlet_oauth_codes ("hash" TEXT PRIMARY KEY, "oauth_client" TEXT NOT NULL REFERENCES "evlet_oauth_clients"("id") ON DELETE CASCADE, "user_id" INTEGER NOT NULL REFERENCES "evlet_users"("id") ON DELETE CASCADE, "redirect_uri" TEXT NOT NULL, "challenge" TEXT NOT NULL, "allow_changes" INTEGER NOT NULL, "expires" INTEGER NOT NULL, "grant_id" INTEGER);
CREATE TABLE evlet_overrides ("kind" TEXT NOT NULL, "key" TEXT NOT NULL, "value" TEXT NOT NULL, "changed_by" INTEGER, "changed_at" INTEGER, PRIMARY KEY ("kind", "key"), CHECK ("kind" IN ('perm', 'field', 'custom', 'layout', 'list', 'naming', 'setting', 'workspace', 'state', 'rule')));
