CREATE TABLE evlet_print_designs ("name" TEXT PRIMARY KEY, "definition" TEXT NOT NULL, "changed_by" TEXT, "changed_at" INTEGER);
CREATE TABLE evlet_releases ("model" TEXT NOT NULL, "record_id" INTEGER NOT NULL, "number" INTEGER NOT NULL, "snapshot" INTEGER NOT NULL, "at" TEXT NOT NULL, "actor" TEXT NOT NULL, "state" TEXT NOT NULL, "hash" TEXT NOT NULL, "drifted" INTEGER NOT NULL DEFAULT 0, "data" TEXT NOT NULL, PRIMARY KEY ("model", "record_id", "number", "snapshot"));
CREATE TABLE evlet_roles ("id" TEXT PRIMARY KEY, "kind" TEXT NOT NULL, "base" TEXT, "realm" TEXT NOT NULL DEFAULT 'desk', "opens_controls" INTEGER NOT NULL DEFAULT 0, "description" TEXT NOT NULL DEFAULT '', "customize_workspaces" INTEGER NOT NULL DEFAULT 0, CHECK ("kind" IN ('framework', 'custom')), CHECK ("realm" IN ('desk', 'portal')));
