CREATE TABLE evlet_tool_approvals (id INTEGER PRIMARY KEY AUTOINCREMENT, "user_id" INTEGER NOT NULL REFERENCES "evlet_users"("id") ON DELETE CASCADE, "origin" TEXT NOT NULL, "client" TEXT, "run_id" INTEGER, "tool" TEXT NOT NULL, "arguments" TEXT NOT NULL, "digest" TEXT NOT NULL, "summary" TEXT NOT NULL, "status" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "expires_at" INTEGER NOT NULL, "decided_at" INTEGER, CHECK ("status" IN ('pending', 'approved', 'declined', 'used', 'expired')));
CREATE TABLE evlet_unsaved ("user_id" INTEGER NOT NULL REFERENCES "evlet_users"("id") ON DELETE CASCADE, "model" TEXT NOT NULL, "record_id" INTEGER NOT NULL, "changes" TEXT NOT NULL, "base_revision" TEXT NOT NULL, "saved_at" INTEGER NOT NULL, "size" INTEGER NOT NULL, "version" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("user_id", "model", "record_id"));
