CREATE TABLE evlet_unsaved_versions ("user_id" INTEGER NOT NULL REFERENCES "evlet_users"("id") ON DELETE CASCADE, "version" INTEGER NOT NULL, PRIMARY KEY ("user_id"));
CREATE TABLE evlet_user_links ("user_id" INTEGER NOT NULL REFERENCES "evlet_users"("id") ON DELETE CASCADE, "model" TEXT NOT NULL, "record_id" INTEGER NOT NULL, PRIMARY KEY ("user_id", "model", "record_id"));
CREATE TABLE evlet_user_prefs ("user_id" INTEGER NOT NULL REFERENCES "evlet_users"("id") ON DELETE CASCADE, "scope" TEXT NOT NULL, "key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("user_id", "scope", "key"));
CREATE TABLE evlet_user_profile ("user_id" INTEGER REFERENCES "evlet_users"("id") ON DELETE CASCADE PRIMARY KEY, "full_name" TEXT NOT NULL DEFAULT '', "short_name" TEXT NOT NULL DEFAULT '', "title" TEXT NOT NULL DEFAULT '', "phone" TEXT NOT NULL DEFAULT '', "email" TEXT NOT NULL DEFAULT '', "photo_file" INTEGER, "signature" TEXT NOT NULL DEFAULT '', "two_step_secret" BLOB, "backup_codes" TEXT, "two_step_since" INTEGER, "two_step_last" INTEGER, "two_step_pending" BLOB, "two_step_agent" TEXT NOT NULL DEFAULT '');
