CREATE TRIGGER "evlet_order_fixed_id" BEFORE UPDATE OF "id" ON "order" WHEN NEW."id" IS NOT OLD."id" BEGIN SELECT RAISE(ABORT, 'order: record ids never change'); END;
CREATE UNIQUE INDEX "evlet_memo_name_unique" ON "memo" ("name");
CREATE TRIGGER "evlet_memo_fixed_id" BEFORE UPDATE OF "id" ON "memo" WHEN NEW."id" IS NOT OLD."id" BEGIN SELECT RAISE(ABORT, 'memo: record ids never change'); END;
CREATE TRIGGER "evlet_tally_fixed_id" BEFORE UPDATE OF "id" ON "tally" WHEN NEW."id" IS NOT OLD."id" BEGIN SELECT RAISE(ABORT, 'tally: record ids never change'); END;
CREATE TRIGGER "evlet_evlet_releases_no_update" BEFORE UPDATE ON "evlet_releases" BEGIN SELECT RAISE(ABORT, 'Releases are never changed'); END;
CREATE TRIGGER "evlet_evlet_releases_no_delete" BEFORE DELETE ON "evlet_releases" BEGIN SELECT RAISE(ABORT, 'Releases are never changed'); END;
CREATE TRIGGER "evlet_evlet_releases_no_replace" BEFORE INSERT ON "evlet_releases" WHEN EXISTS (SELECT 1 FROM "evlet_releases" WHERE "model" = NEW."model" AND "record_id" = NEW."record_id" AND "number" = NEW."number" AND "snapshot" = NEW."snapshot") BEGIN SELECT RAISE(ABORT, 'Releases are never changed'); END;
